const COUNTRY_ALIASES={'united states of america':'united states','usa':'united states','uk':'united kingdom','russia':'russian federation','syria':'syrian arab republic','iran':'iran (islamic republic of)','turkey':'turkey','türkiye':'turkey','south korea':'korea (republic of)','north korea':'korea (democratic people\'s republic of)','vietnam':'viet nam','laos':'lao people\'s democratic republic','bolivia':'bolivia (plurinational state of)','venezuela':'venezuela (bolivarian republic of)','tanzania':'tanzania, united republic of','brunei':'brunei darussalam','moldova':'moldova (republic of)','czech republic':'czechia'};
let countryDataset=null,countryLoad=null;
const COUNTRY_REMOTE='https://raw.githubusercontent.com/johnwwoodman/CoreForge-Global-OSINT-Dashboard/main/data/country-facts.json';
const COUNTRY_CACHE_KEY='cf-country-snapshot-v1';
function normCountry(s){return String(s||'').toLocaleLowerCase('en').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,' ').trim()}
function validCountrySnapshot(d){return d&&typeof d==='object'&&d.countries&&Object.keys(d.countries).length>=200}
async function getCountryData(){
 if(countryDataset)return countryDataset;
 if(countryLoad)return countryLoad;
 countryLoad=(async()=>{
  let bundled=null,cached=null;
  try{const r=await fetch('data/country-facts.json?version=1.5.0',{cache:'no-store'});if(r.ok){const d=await r.json();if(validCountrySnapshot(d))bundled=d}}catch{}
  try{const d=JSON.parse(localStorage.getItem(COUNTRY_CACHE_KEY)||'null');if(validCountrySnapshot(d))cached=d}catch{}
  const localEdition=['127.0.0.1','localhost'].includes(location.hostname)||location.protocol==='file:';
  // On Windows always prefer the latest published snapshot; never replace a good cached snapshot with an old bundle.
  let remote=null;
  if(localEdition){try{const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),12000);
   try{const r=await fetch(COUNTRY_REMOTE+'?t='+Date.now(),{cache:'no-store',signal:controller.signal});if(r.ok){const d=await r.json();if(validCountrySnapshot(d))remote=d}}finally{clearTimeout(timer)}
  }catch{}}
  const pick=(remote&&(!cached||String(remote.updated||'')>=String(cached.updated||'')))?remote:
   (cached&&(!bundled||String(cached.updated||'')>=String(bundled.updated||'')))?cached:bundled;
  countryDataset=pick||{countries:{}};
  countryDataset._syncStatus=remote&&countryDataset===remote?'Live GitHub snapshot':cached&&countryDataset===cached?'Offline cached snapshot':'Bundled snapshot';
  if(remote){try{localStorage.setItem(COUNTRY_CACHE_KEY,JSON.stringify(remote))}catch{}}
  return countryDataset;
 })();return countryLoad;
}
function matchCountry(name,d){const n=normCountry(name);const alias=normCountry(COUNTRY_ALIASES[n]||name);const vals=Object.values(d?.countries||{});return vals.find(x=>[x.name,...(x.aliases||[])].some(v=>normCountry(v)===n||normCountry(v)===alias))||null}
function relatedCountryArticles(name){const n=normCountry(name);if(!n)return[];const aliases=[n];if(n==='united states of america')aliases.push('united states');if(n==='united kingdom')aliases.push('britain');const rx=new RegExp('(^|[^a-z])('+aliases.map(x=>x.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')+')([^a-z]|$)','i');return (Array.isArray(records)?records:[]).filter(a=>rx.test([a.title,a.description,a.summary,a.country,a.region].filter(Boolean).join(' '))).slice(0,8)}
function renderCountryFacts(node,name){
 if(!node||!name)return;const target=node.querySelector('.country-profile-content');if(!target)return;
 const token=name.trim();target.innerHTML='<p class="small muted">Loading country intelligence…</p>';
 getCountryData().then(snapshot=>{
  if(!node.isConnected||node.querySelector('[data-country-search]')?.value.trim()!==token)return;
  const d=matchCountry(token,snapshot);
  const v=x=>x===null||x===undefined||x===''?'Not available':x;
  const fmt=x=>Number.isFinite(Number(x))&&x!==null&&x!==undefined&&x!==''?Number(x).toLocaleString('en-GB'):'Not available';
  const pYear=d?.populationYear?` (${d.populationYear})`:'';
  const government=d?.governmentType||'Not yet available from source';
  const leadership=d?.leadershipStatus||'Not independently verified';
  const fields=[['Capital',v(d?.capital)],['Population',fmt(d?.population)+pYear],['Currency',v(d?.currency)],['Languages',v(d?.languages)],['Region',v(d?.region)],['Government type',government],['Head of state',v(d?.headOfState)],['Head of government',v(d?.headOfGovernment)],['GDP (current US$)',d?.gdpUsd?'$'+fmt(Math.round(d.gdpUsd))+(d.gdpUsdYear?' ('+d.gdpUsdYear+')':''):'Not available']];
  const wiki='https://www.wikidata.org/w/index.php?search='+encodeURIComponent(token);
  const bbc='https://www.bbc.com/news/world';
  const articles=relatedCountryArticles(token);
  const status=snapshot?._syncStatus||(snapshot?.sourcesSucceeded?.length?'Automated data available':'Bundled reference snapshot');
  const urls=[['Population (World Bank)',d?.populationSource],['GDP (World Bank)',d?.gdpUsdSource],['Political data (Wikidata)',d?.leadershipSource||wiki],['BBC World reporting',bbc]];
  const link=(url,label)=>{try{const u=new URL(url);return u.protocol==='https:'?`<a href="${safe(u.href)}" target="_blank" rel="noopener noreferrer">${safe(label)} ↗</a>`:''}catch{return ''}};
  const primaryCurrency=String(d?.currency||'Not available').split(', ')[0];
  fields[2][1]=primaryCurrency;
  const lastChecked=d?.leadershipChecked||'Not checked';
  const coverage=snapshot?.leadershipCoverage;
  const coverageText=coverage?` · Worldwide leadership coverage: ${coverage.countriesWithAnyLeader}/${coverage.countriesTotal} · Both fields: ${coverage.countriesWithBothLeaders??'—'}`:'';
  const sources=(snapshot?.sourcesSucceeded||[]).map(x=>`<li>${safe(x)}</li>`).join('');
  const errors=(snapshot?.sourceErrors||[]).map(x=>`<li>${safe(x)}</li>`).join('');
  const savedNote=localStorage.getItem('cf-country-note-'+normCountry(token))||'';
  target.innerHTML=`<h3>${safe(d?.name||token)}</h3><p class="small muted country-status">Data snapshot: ${safe(snapshot?.updated||'unknown')} · ${safe(status)}</p><dl class="country-facts">${fields.map(([k,val])=>`<dt>${safe(k)}</dt><dd>${safe(val)}</dd>`).join('')}</dl><p class="small muted">Leadership: ${safe(leadership)} · Last checked: ${safe(lastChecked)}. Automated candidates are not independently verified.${safe(coverageText)}</p><details class="country-diagnostics"><summary>Data sources and collection diagnostics</summary><p class="small muted">Provider results are global, not a guarantee every country was updated.</p><ul>${sources||'<li>No successful source listed</li>'}${errors}</ul></details><div class="country-actions"><button type="button" data-country-copy>Copy country summary</button><button type="button" data-country-save>Save note</button></div><label class="country-note-label">Analyst notes (stored only in this browser)<textarea data-country-note placeholder="Add your own context, caveats and assessment…">${safe(savedNote)}</textarea></label><p class="small country-links">${urls.map(([label,url])=>url?link(url,label):'').filter(Boolean).join(' · ')}</p><h4>Related intelligence <small>(${articles.length})</small></h4>${articles.length?'<ul class="country-related">'+articles.map(a=>`<li>${a.published?'<small>'+safe(String(a.published).slice(0,10))+' · '+safe(a.source||'Source')+'</small> ':''}<a target="_blank" rel="noopener noreferrer" href="${safe(a.url||a.link||'#')}">${safe(a.title||'Source article')}</a></li>`).join('')+'</ul>':'<p class="small muted">No matching articles in the current intelligence snapshot.</p>'}`;
  target.querySelector('[data-country-save]').onclick=()=>{localStorage.setItem('cf-country-note-'+normCountry(token),target.querySelector('[data-country-note]').value);target.querySelector('[data-country-save]').textContent='Saved ✓'};
  target.querySelector('[data-country-copy]').onclick=async()=>{const summary=[d?.name||token,...fields.map(([k,v])=>k+': '+v),'Data snapshot: '+(snapshot?.updated||'unknown'),'Leadership status: '+leadership].join('\n');try{await navigator.clipboard.writeText(summary);target.querySelector('[data-country-copy]').textContent='Copied ✓'}catch{target.querySelector('[data-country-copy]').textContent='Copy unavailable'}};

 });
}

const mapStates={};
const viewForRegion=()=>MAP_VIEWS[prefs.region]||MAP_VIEWS.all;
const mapView=()=>mapStates[prefs.region]||viewForRegion();
function clampMapView(v){let [x,y,w,h]=v;w=Math.max(18,Math.min(1000,w));h=Math.max(9,Math.min(500,h));x=Math.max(0,Math.min(1000-w,x));y=Math.max(0,Math.min(500-h,y));return [x,y,w,h]}
function setMapView(svg,view){const v=clampMapView(view);mapStates[prefs.region]=v;svg.setAttribute('viewBox',v.join(' '));}
function setupMapInteraction(box){const svg=box.querySelector('svg');if(!svg)return;
 const zoom=(factor)=>{const [x,y,w,h]=mapView(),nw=w*factor,nh=h*factor;setMapView(svg,[x+(w-nw)/2,y+(h-nh)/2,nw,nh])};
 box.querySelector('[data-map-zoom-in]').onclick=()=>zoom(.75);
 box.querySelector('[data-map-zoom-out]').onclick=()=>zoom(1/.75);
 box.querySelector('[data-map-reset]').onclick=()=>{delete mapStates[prefs.region];svg.setAttribute('viewBox',mapView().join(' '));$('status').textContent='Map reset to '+(prefs.region==='all'?'Worldwide':prefs.region)};
 svg.addEventListener('wheel',e=>{e.preventDefault();const rect=svg.getBoundingClientRect();const [x,y,w,h]=mapView();const scale=Math.min(rect.width/w,rect.height/h);const offsetX=(rect.width-w*scale)/2,offsetY=(rect.height-h*scale)/2;const px=(e.clientX-rect.left-offsetX)/scale+x,py=(e.clientY-rect.top-offsetY)/scale+y;const f=e.deltaY>0?1.15:1/1.15;const nw=w*f,nh=h*f;setMapView(svg,[px-(px-x)*f,py-(py-y)*f,nw,nh])},{passive:false});
 let dragging=false,last=null,moved=false;
 svg.addEventListener('pointerdown',e=>{if(e.button!==0)return;dragging=true;moved=false;last=[e.clientX,e.clientY];svg.setPointerCapture(e.pointerId);svg.classList.add('panning')});
 svg.addEventListener('pointermove',e=>{if(!dragging||!last)return;const dx=e.clientX-last[0],dy=e.clientY-last[1];if(Math.abs(dx)+Math.abs(dy)>2)moved=true;const [x,y,w,h]=mapView();const rect=svg.getBoundingClientRect();const scale=Math.min(rect.width/w,rect.height/h);setMapView(svg,[x-dx/scale,y-dy/scale,w,h]);last=[e.clientX,e.clientY]});
 const end=()=>{dragging=false;last=null;svg.classList.remove('panning');if(moved){svg.dataset.ignoreClick='1';setTimeout(()=>delete svg.dataset.ignoreClick,0)}};
 svg.addEventListener('pointerup',end);svg.addEventListener('pointercancel',end);
 svg.addEventListener('click',e=>{if(svg.dataset.ignoreClick){e.stopPropagation();e.preventDefault()}},true);
}
const snapshot=window.COREFORGE_FEED;
if(snapshot&&Array.isArray(snapshot.records)){records=snapshot.records;feedUpdated=snapshot.updated||null;feedErrors=snapshot.errors||[];sourceHealth={checked:snapshot.sources_checked,ok:snapshot.sources_ok,version:snapshot.collector_version||null}}
try{const p=JSON.parse(localStorage.getItem('coreforge-prefs'));if(p?.layouts&&p.workspace in WORKSPACES)prefs={...prefs,...p,layouts:{...prefs.layouts,...p.layouts}}}catch{}
for(const layout of Object.values(prefs.layouts)){if(Array.isArray(layout)&&layout.some(w=>w.type==='map')&&!layout.some(w=>w.type==='country'))layout.splice(layout.findIndex(w=>w.type==='map')+1,0,{id:'country-v11',type:'country',size:'medium'})}
// Do not restore the old directory-as-feed state from previous releases.
try{const d=JSON.parse(localStorage.getItem('coreforge-records'));if(Array.isArray(d)&&d.some(r=>r&&r.source&&!DIRECTORY.some(x=>x.url===r.url))){records=d;imported=true}else localStorage.removeItem('coreforge-records')}catch{}
const save=()=>{try{localStorage.setItem('coreforge-prefs',JSON.stringify(prefs));if(imported)localStorage.setItem('coreforge-records',JSON.stringify(records));else localStorage.removeItem('coreforge-records')}catch(e){$('status').textContent='Storage unavailable: changes may not persist'}};
const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const validUrl=s=>{try{const u=new URL(s);return ['https:','http:'].includes(u.protocol)?u.href:null}catch{return null}};
const filtered=()=>records.filter(r=>!disabledSources().has(r.source)&&(!prefs.mappedOnly||(r.lat!==undefined&&r.lon!==undefined))&&(!prefs.watchTerms||prefs.watchTerms.split(',').map(x=>x.trim().toLowerCase()).filter(Boolean).some(term=>[r.title,r.description,r.source].join(' ').toLowerCase().includes(term)))&&matchesRegion(r)&&(prefs.category==='all'||r.category===prefs.category)&&(!prefs.sourceFilter||prefs.sourceFilter==='all'||r.source===prefs.sourceFilter)&&(!prefs.savedOnly||savedArticles.has(r.url))&&(!prefs.ageDays||!r.published||(Date.now()-new Date(r.published).getTime())<=Number(prefs.ageDays)*86400000)&&(!$('search').value||[r.title,r.source,r.description,r.country].join(' ').toLowerCase().includes($('search').value.toLowerCase())));
// v0.8: local-only AI analysis. The server binds exclusively to 127.0.0.1.
const aiState={busy:false,controller:null,result:null,workspace:null,sourceList:[],error:''};
const aiCacheKey=()=>`coreforge-ai-v08-${prefs.workspace}`;
function analystBody(){
 const local=['localhost','127.0.0.1'].includes(location.hostname)&&location.port==='8765';
 const result=aiState.workspace===prefs.workspace?aiState.result:null;
 return `<div class="ai-panel"><p class="small muted">${local?'Local analysis bridge detected. Ollama runs on this computer.':'AI is optional. Open this dashboard using the local launcher to enable it; GitHub Pages remains read-only.'}</p>
 <div class="ai-controls"><label>Model <select data-ai-model><option value="qwen3:8b">Qwen3 8B · detailed</option><option value="qwen3:4b">Qwen3 4B · faster</option></select></label><label>Reports <select data-ai-count><option value="8">8 · quick</option><option value="12" selected>12 · balanced</option><option value="20">20 · detailed</option><option value="30">30 · extensive</option></select></label></div>
 <label class="ai-question-label" for="ai-question">Ask about the selected workspace</label><textarea id="ai-question" data-ai-question rows="3" maxlength="800" placeholder="What are the key developments and possible CMI/CIMIC implications over the past seven days?"></textarea>
 <div class="ai-buttons"><button data-ai-brief ${!local||aiState.busy?'disabled':''}>Generate intelligence assessment</button><button data-ai-ask ${!local||aiState.busy?'disabled':''}>Ask question</button><button data-ai-cancel ${!aiState.busy?'disabled':''}>Cancel</button><button data-ai-export ${!result?'disabled':''}>Export assessment</button></div>
 <p class="ai-status" data-ai-status aria-live="polite">${safe(aiState.error||(aiState.busy?'Analysing local reporting. CPU processing may take several minutes. The local server does not yet stream partial output.':local?'Ready · only public feed data is sent to your local Ollama.':'Start the local launcher to enable AI.'))}</p>
 <pre class="ai-output" data-ai-output>${safe(result?.text||'')}</pre><div class="ai-references" data-ai-references>${result?aiRefsHtml(result.sources):''}</div>
 <p class="small muted">AI-generated analysis can contain errors. References identify supplied reports, not proof of individual claims. Verify original reporting before operational use. Do not enter classified or sensitive information.</p></div>`;
}
function aiRefsHtml(sources){return sources?.length?'<h4>Reports supplied to model</h4><ol>'+sources.map((r,i)=>`<li>[${i+1}] <a href="${safe(validUrl(r.url)||'#')}" target="_blank" rel="noopener noreferrer">${safe(r.title)}</a> · ${safe(r.source)}</li>`).join('')+'</ol>':''}
function aiSelectedReports(max){const cutoff=Date.now()-7*86400000;const items=filtered().filter(r=>r.kind!=='podcast'&&validUrl(r.url)).filter(r=>!r.published||Number.isNaN(Date.parse(r.published))||Date.parse(r.published)>=cutoff).sort((a,b)=>(Date.parse(b.published)||0)-(Date.parse(a.published)||0));const selected=[],counts={};for(const r of items){const key=r.source||'Unknown';if((counts[key]||0)>=4)continue;counts[key]=(counts[key]||0)+1;selected.push(r);if(selected.length>=max)break}return selected.map(r=>({title:String(r.title||'').slice(0,240),source:String(r.source||'').slice(0,100),description:String(r.description||'').slice(0,550),published:String(r.published||'').slice(0,60),category:String(r.category||'').slice(0,60),url:validUrl(r.url),place:String(r.place||'').slice(0,80)}))}
function setupAnalystWidget(){const box=document.querySelector('.ai-panel');if(!box)return;const model=box.querySelector('[data-ai-model]');const count=box.querySelector('[data-ai-count]');model.value=localStorage.getItem('coreforge-ai-model')||'qwen3:8b';count.value=localStorage.getItem('coreforge-ai-count')||'12';model.onchange=()=>localStorage.setItem('coreforge-ai-model',model.value);count.onchange=()=>localStorage.setItem('coreforge-ai-count',count.value);let saved=null;try{saved=JSON.parse(localStorage.getItem(aiCacheKey())||'null')}catch{}if(!aiState.busy&&aiState.workspace!==prefs.workspace&&saved){aiState.workspace=prefs.workspace;aiState.result=saved;box.querySelector('[data-ai-output]').textContent=saved.text||'';box.querySelector('[data-ai-references]').innerHTML=aiRefsHtml(saved.sources);box.querySelector('[data-ai-export]').disabled=false}
 box.querySelector('[data-ai-brief]').onclick=()=>runAnalysis('assessment',box);
 box.querySelector('[data-ai-ask]').onclick=()=>runAnalysis('question',box);
 box.querySelector('[data-ai-cancel]').onclick=()=>{aiState.controller?.abort();box.querySelector('[data-ai-status]').textContent='Browser request cancelled. Ollama may continue processing on the local server until it finishes.'};
 box.querySelector('[data-ai-export]').onclick=()=>{const r=aiState.result;if(!r)return;const refs=(r.sources||[]).map((x,i)=>`[${i+1}] ${x.source} — ${x.title} — ${x.url}`).join('\n');const blob=new Blob([r.text+'\n\nSOURCE REPORTS\n'+refs],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`coreforge-${prefs.workspace}-ai-assessment.txt`;link.click();setTimeout(()=>URL.revokeObjectURL(url),500)};
}
async function runAnalysis(mode,box){if(aiState.busy)return;const question=box.querySelector('[data-ai-question]').value.trim();if(mode==='question'&&!question){box.querySelector('[data-ai-status]').textContent='Enter a question first.';return}const reports=aiSelectedReports(Number(box.querySelector('[data-ai-count]').value));if(!reports.length){box.querySelector('[data-ai-status]').textContent='No matching recent source reports. Widen workspace filters or refresh the feed.';return}aiState.busy=true;aiState.controller=new AbortController();aiState.error='';const workspace=prefs.workspace;const status=box.querySelector('[data-ai-status]');const output=box.querySelector('[data-ai-output]');status.textContent=`Analysing ${reports.length} reports using ${box.querySelector('[data-ai-model]').value} on this computer…`;const started=Date.now();const progress=setInterval(()=>{if(aiState.busy&&box.isConnected)status.textContent=`Analysing ${reports.length} reports · ${Math.floor((Date.now()-started)/1000)} seconds elapsed · CPU inference`;},1000);output.textContent='';box.querySelector('[data-ai-brief]').disabled=true;box.querySelector('[data-ai-ask]').disabled=true;box.querySelector('[data-ai-cancel]').disabled=false;const model=box.querySelector('[data-ai-model]').value;
 try{const response=await fetch('/api/ai/analyse',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mode,question,workspace:WORKSPACES[workspace]?.name||workspace,model,reports}),signal:aiState.controller.signal});const data=await response.json();if(!response.ok)throw Error(data.error||`HTTP ${response.status}`);if(workspace!==prefs.workspace){status.textContent='Assessment finished for a different workspace; switch back to view it.';return}aiState.workspace=workspace;aiState.result={text:data.text,sources:reports,created:new Date().toISOString()};try{localStorage.setItem(aiCacheKey(),JSON.stringify(aiState.result))}catch{}output.textContent=data.text;box.querySelector('[data-ai-references]').innerHTML=aiRefsHtml(reports);box.querySelector('[data-ai-export]').disabled=false;status.textContent=`Completed · ${reports.length} supplied reports · ${new Date().toLocaleTimeString()}`}
 catch(err){status.textContent=err.name==='AbortError'?'Analysis cancelled.':`AI connection failed: ${err.message}`}
 finally{clearInterval(progress);aiState.busy=false;aiState.controller=null;box.querySelector('[data-ai-brief]').disabled=false;box.querySelector('[data-ai-ask]').disabled=false;box.querySelector('[data-ai-cancel]').disabled=true}
}
function drawDirectory(){const e=$('widget-library');e.innerHTML=Object.entries(TYPES).map(([k,v])=>`<div class="widget-option"><span>${safe(v)}</span><button data-add="${k}" aria-label="Add ${safe(v)}">＋</button></div>`).join('');e.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>add(b.dataset.add))}
function add(type){const layout=prefs.layouts[prefs.workspace];layout.push({id:type+'-'+Date.now(),type,size:type==='map'?'large':'medium'});save();render()}
function refreshMapLayers(box){if(!box)return;const group=box.querySelector('[data-layer-geometry]');if(group)group.innerHTML=layerGeometry();const pins=box.querySelector('[data-intelligence-pins]');if(pins)pins.style.display=GEO_LAYERS.intelligence?'':'none';bindGeoLocations(box)}
function bindGeoLocations(box){box.querySelectorAll('[data-geo-name]').forEach(el=>{const show=()=>{const detail=box.querySelector('.map-detail');if(detail)detail.innerHTML='<strong>'+safe(el.dataset.geoName)+'</strong> — '+safe(el.dataset.geoDescription)+'<br><small>Reference location; not a live movement or incident report.</small>';};el.addEventListener('click',show);el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();show()}})})}
function drawMap(items){
 const polys=world?.features||[], paths=[];
 const ringPath=rings=>rings.map(ring=>ring.map((pt,i)=>`${i?'L':'M'}${((pt[0]+180)/360*1000).toFixed(2)},${((90-pt[1])/180*500).toFixed(2)}`).join(' ')+' Z').join(' ');
 for(const f of polys){const g=f.geometry;if(!g)continue;const parts=g.type==='Polygon'?[g.coordinates]:g.type==='MultiPolygon'?g.coordinates:[];
 // Each disconnected territory gets its own clickable shape. France and French Guiana are not visually linked.
 parts.forEach((part,i)=>paths.push(`<path class="land" d="${ringPath(part)}" data-country="${safe(f.properties?.name)}" data-part="${i}" tabindex="0" role="button" aria-label="Select ${safe(f.properties?.name)} territory"><title>${safe(f.properties?.name)}</title></path>`));}
 const pins=(GEO_LAYERS.intelligence?items:[]).filter(r=>Number.isFinite(Number(r.lat))&&Number.isFinite(Number(r.lon))&&r.lat!==undefined&&r.lon!==undefined).slice(0,200).map(r=>`<circle class="pin" cx="${(Number(r.lon)+180)/360*1000}" cy="${(90-Number(r.lat))/180*500}" r="4" tabindex="0" role="link" data-pin-url="${safe(validUrl(r.url)||'')}" data-pin-title="${safe(r.title)}" data-pin-place="${safe(r.place||'Approximate reference')}" data-pin-source="${safe(r.source||'Unknown')}" aria-label="Open article: ${safe(r.title)}"><title>${safe(r.place||'Approximate location')} · ${safe(r.title)} · ${safe(r.location_precision||'Imported coordinates')}</title></circle>`).join('');
 const [x,y,w,h]=mapView();const name=prefs.region==='all'?'Worldwide':prefs.region;
 return `<div class="map-panel"><div class="mapbox"><svg viewBox="${x} ${y} ${w} ${h}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="${safe(name)} geographic map"><g>${paths.join('')}</g><g data-layer-geometry>${layerGeometry()}</g><g data-intelligence-pins>${pins}</g></svg><div class="map-detail" id="map-detail" aria-live="polite">Select a marker to inspect its source. Markers are headline references, not confirmed event locations.</div><div class="maplabel">${safe(name)} · ${world?'Natural Earth geography':'Map loading'} · ${items.filter(r=>r.lat!==undefined&&r.lon!==undefined).length} mapped records</div><div class="mapcontrols"><button type="button" data-map-zoom-in title="Zoom in" aria-label="Zoom in">＋</button><button type="button" data-map-zoom-out title="Zoom out" aria-label="Zoom out">－</button><button type="button" class="mapreset" title="Return to workspace region" data-map-reset>⌖ Region view</button></div></div>${layerControls()}</div>`;
}
function briefForWorkspace(){
 const region=WORKSPACES[prefs.workspace]?.region||'all';
 const now=new Date(), cutoff=now.getTime()-7*86400000;
 const recent=records.filter(r=>r.published&&Number.isFinite(new Date(r.published).getTime())&&new Date(r.published).getTime()>=cutoff&&(region==='all'||recordRegions(r).includes(region)||(r.region==='all'&&!Array.isArray(r.regions))));
 const ranked=[...recent].sort((a,b)=>new Date(b.published)-new Date(a.published));
 const unique=[],seen=new Set(),sourceCount={};
 for(const r of ranked){const key=(r.title||'').toLowerCase().replace(/[^a-z0-9]/g,'').slice(0,90);if(!key||seen.has(key))continue;if((sourceCount[r.source]||0)>=3)continue;seen.add(key);sourceCount[r.source]=(sourceCount[r.source]||0)+1;unique.push(r);if(unique.length>=18)break}
 if(!unique.length)return null;
 const selected=unique.slice(0,9);
 const groups=Object.groupBy?Object.groupBy(selected,r=>r.category||'Other'):selected.reduce((o,r)=>((o[r.category||'Other']??=[]).push(r),o),{});
 const sections=Object.entries(groups).map(([category,rows])=>{const sample=rows.slice(0,3);return `${category}: ${sample.map(r=>{const detail=(r.description||'').replace(/\s+/g,' ').trim();const extra=detail&&!detail.toLowerCase().startsWith(r.title.toLowerCase().slice(0,35))?` ${detail.slice(0,165)}`:'';return `${r.title.replace(/[.!?]+$/,'')}.${extra} (Reporting: ${r.source}.)`}).join(' ')}`});
 const label=WORKSPACES[prefs.workspace]?.name||'Custom';
 const text=`${label} — weekly open-source briefing. Reporting window: seven days ending ${now.toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'})}. Coverage includes ${selected.length} selected reports from ${new Set(selected.map(r=>r.source)).size} publishers. ${sections.join(' ')} Coverage gaps: this summary reflects only the feeds successfully collected, and is not a comprehensive picture of events. Source reports are unverified by CoreForge. For detail and competing accounts, consult the original articles.`;
 return {text,generated:now.toISOString(),items:selected.map(r=>({title:r.title,url:r.url,source:r.source}))};
}
function briefBody(){const b=briefForWorkspace();if(!b)return '<p class="empty">No weekly brief available yet. Import dated reporting or publish the scheduled GitHub workflow to generate one.</p>';
 const links=(b.items||[]).slice(0,12).map(r=>{const u=validUrl(r.url);return u?`<li><a href="${safe(u)}" target="_blank" rel="noopener noreferrer">${safe(r.title)}</a> <small>— ${safe(r.source)}</small></li>`:''}).join('');
 return `<div class="brief-controls"><button type="button" data-read-brief>▶ Read aloud</button><button type="button" data-stop-brief>■ Stop</button><button type="button" data-download-brief>↓ Save text</button></div><p class="small muted">${b.generated?'Generated: '+safe(new Date(b.generated).toLocaleString('en-GB')):'Weekly briefing'} · Spoken using your browser voice.</p><p class="brief-text">${safe(b.text)}</p><details><summary>Original reporting (${(b.items||[]).length})</summary><ol class="brief-links">${links}</ol></details>`;
}
function card(r){const u=validUrl(r.url);return `<article class="record"><button class="save-article ${savedArticles.has(r.url)?'saved':''}" type="button" data-save-url="${safe(r.url||'')}" title="Save or unsave article" aria-label="${savedArticles.has(r.url)?'Remove saved article':'Save article'}">${savedArticles.has(r.url)?'★':'☆'}</button><div><span class="tag">${safe(r.category||'Other')}</span><small>${safe(r.region||'Worldwide')} · ${safe(r.source||'Unknown source')}</small></div>${u?`<a href="${safe(u)}" target="_blank" rel="noopener noreferrer">${safe(r.title)}</a>`:`<strong>${safe(r.title)}</strong>`}<p>${safe(r.description||'')}</p>${r.published?`<small>Published: ${safe(r.published)}</small>`:''}${r.place?`<small> · Approximate ${safe(r.location_precision==='country-centroid'?'country reference':'place reference')}: ${safe(r.place)} (headline match; not verified event location)</small>`:''}</article>`}
function feedBody(items){
 const w=(prefs.layouts[prefs.workspace]||[]).find(w=>w.type==='feed');
 const limit=[5,10,20,50].includes(Number(w?.feedLimit))?Number(w.feedLimit):10;
 const page=Math.max(0,Math.min(Number(w?.feedPage)||0,Math.max(0,Math.ceil(items.length/limit)-1)));
 if(w)w.feedPage=page;
 const start=page*limit;
 return `<div class="feed-pagination"><button type="button" data-export-csv title="Export all currently filtered articles">↓ CSV</button><label>Articles per page <select data-feed-limit aria-label="Articles per page">${[5,10,20,50].map(n=>`<option value="${n}" ${n===limit?'selected':''}>${n}</option>`).join('')}</select></label><span>${items.length?`${start+1}–${Math.min(start+limit,items.length)} of ${items.length}`:'No matching articles'}</span><button type="button" data-feed-prev ${page===0?'disabled':''}>Previous</button><button type="button" data-feed-next ${start+limit>=items.length?'disabled':''}>Next</button></div>`+(items.length?items.slice(start,start+limit).map(card).join(''):'<p class="empty">No articles match these filters.</p>');
}
function body(type,items){if(type==='analyst')return analystBody();if(type==='health'){const last=feedUpdated?new Date(feedUpdated):null;const age=last&&!Number.isNaN(last.getTime())?Math.round((Date.now()-last.getTime())/3600000):null;const mapped=records.filter(r=>Number.isFinite(Number(r.lat))&&Number.isFinite(Number(r.lon))&&r.lat!==undefined&&r.lon!==undefined).length;return `<div class="health-grid"><div><b>${records.length}</b><small>Collected records</small></div><div><b>${mapped}</b><small>Approx. place references</small></div><div><b>${sourceHealth?.ok??'—'} / ${sourceHealth?.checked??'—'}</b><small>Responding feeds</small></div><div><b>${age===null?'—':age+' h'}</b><small>Snapshot age</small></div></div><p class="small muted">Collector ${safe(sourceHealth?.version||'unknown')} · ${feedErrors.length} feed errors. Place references are not confirmed incidents. · ${records.filter(r=>r.kind==='podcast').length} podcast episodes · ${records.filter(r=>r.kind==='research').length} research items.</p>${age!==null&&age>8?'<p class="health-warning">Snapshot is older than eight hours. Check the GitHub collection workflow.</p>':''}`;}if(type==='brief')return briefBody();if(type==='map')return drawMap(items);if(type==='feed')return feedBody(items);if(type==='podcasts'){
 const tabs=[['podcast','🎧 Podcasts'],['research','📚 Research'],['directory','🌐 Directory']];
 const header='<div class="publication-tabs" role="tablist" aria-label="Publication type">'+tabs.map(([key,label])=>`<button type="button" role="tab" data-publication-tab="${key}" aria-selected="${publicationTab===key}" class="${publicationTab===key?'active':''}">${label}</button>`).join('')+'</div>';
 // Publication tabs use the live dataset, independent of news-only controls such as
 // map-only, date, category, saved items and watch terms. Respect region and disabled publishers.
 const eligible=records.filter(r=>publicationTab!=='directory'&&r.kind===publicationTab&&!disabledSources().has(r.source)&&matchesRegion(r));
 const directory=DIRECTORY.filter(r=>(prefs.region==='all'||r.region==='all'||r.region===prefs.region)&&(prefs.category==='all'||r.category===prefs.category));
 const list=publicationTab==='directory'?directory:eligible;
 const notice=publicationTab==='directory'?'Publisher directory — links to organisations, not fetched episodes or reports.':publicationTab==='podcast'?'Collected podcast episodes. Audio playback appears only when a feed supplies an audio enclosure.':'Collected research and long-form publications. Check publication dates; older items are not current reporting.';
 const limit=publicationLimits[publicationTab];
 const page=Math.min(publicationPages[publicationTab]||0,Math.max(0,Math.ceil(list.length/limit)-1));
 publicationPages[publicationTab]=page;
 const start=page*limit;
 const pager=`<div class="feed-pagination"><label>Items per page <select data-publication-limit aria-label="Items per page">${[5,10,20,50].map(n=>`<option value="${n}" ${n===limit?'selected':''}>${n}</option>`).join('')}</select></label><span>${list.length?`${start+1}–${Math.min(start+limit,list.length)} of ${list.length}`:'No matching items'}</span><button type="button" data-publication-prev ${page===0?'disabled':''}>Previous</button><button type="button" data-publication-next ${start+limit>=list.length?'disabled':''}>Next</button></div>`;
 const entries=list.slice(start,start+limit).map(r=>`<article class="publication-entry"><a href="${safe(validUrl(r.url)||'#')}" target="_blank" rel="noopener noreferrer">${safe(r.title)}</a><div class="publication-meta">${safe(r.source||'Unknown publisher')}${r.published?' · '+safe(new Date(r.published).toLocaleDateString('en-GB')):''}${r.published&&Date.now()-Date.parse(r.published)>30*86400000?' · ARCHIVE':''}</div><p class="publication-description">${safe(r.description||'No description supplied by publisher.')}</p>${publicationTab==='podcast'&&validUrl(r.audio_url)?`<audio controls preload="none" src="${safe(validUrl(r.audio_url))}" aria-label="Play ${safe(r.title)}"></audio>`:''}</article>`).join('');
 return header+`<p class="feednotice">${notice}</p>`+pager+(entries||'<p class="empty">'+(publicationTab==='podcast'?'No podcast episodes match this workspace. Try Global Overview, or check podcast-source collection errors in Data Health. The Directory tab links to specialist publishers.':'No matching entries in this tab. Try another region or the Directory tab.')+'</p>');
 }if(type==='country'){return countryProfile()}if(type==='trends'){const a=Object.entries(items.reduce((o,r)=>(o[r.category||'Other']=(o[r.category||'Other']||0)+1,o),{})).sort((a,b)=>b[1]-a[1]);return a.length?a.map(([n,v])=>`<div class="statrow"><label>${safe(n)}</label><div class="bar"><i style="width:${v/a[0][1]*100}%"></i></div><b>${v}</b></div>`).join('')+'<p class="small muted">Record counts only; not an assessment of real-world incident frequency.</p>':'<p class="empty">No data available.</p>'}if(type==='sources'){
 const all=[...new Set([...records,...DIRECTORY].map(x=>x.source).filter(Boolean))].sort();
 const disabled=disabledSources();
 const rows=all.filter(name=>prefs.region==='all'||records.some(r=>r.source===name&&matchesRegion(r))||DIRECTORY.some(r=>r.source===name&&(r.region==='all'||r.region===prefs.region)));
 const health=sourceHealth?.checked!=null?`${sourceHealth.ok} / ${sourceHealth.checked} feeds responding`:'No feed health metadata';
 return `<p class="small muted">${safe(health)} · ${feedErrors.length} reported collection error(s). Enable/disable sources for this workspace only; source selection never changes the collected dataset.</p><div class="source-list">${rows.map(name=>{const n=records.filter(r=>r.source===name).length;return `<label class="source-row"><input type="checkbox" data-source-toggle="${safe(name)}" ${disabled.has(name)?'':'checked'}><span><strong>${safe(name)}</strong><small>${n} collected entries · ${DIRECTORY.some(d=>d.source===name)?'directory listing available':'feed publisher'}</small></span></label>`}).join('')}</div>${feedErrors.length?`<details><summary>Collection errors (${feedErrors.length})</summary>${feedErrors.map(e=>`<p class="small">${safe(e.source)}: ${safe(e.message)}</p>`).join('')}</details>`:''}`;
}return ''}
