$('refresh-data').onclick=async()=>{if(location.protocol==='file:'){$('status').textContent='Local file: use a newly downloaded snapshot ZIP to update headlines';return}try{const r=await fetch('data/live-feed.json?ts='+Date.now(),{cache:'no-store'});if(!r.ok)throw Error('HTTP '+r.status);const d=await r.json();if(!Array.isArray(d.records))throw Error('Invalid feed');records=d.records;feedUpdated=d.updated||null;feedErrors=d.errors||[];sourceHealth={checked:d.sources_checked,ok:d.sources_ok,version:d.collector_version||null};imported=false;save();render();$('status').textContent='Feed refreshed'}catch(e){$('status').textContent='Feed update unavailable: '+e.message}};
